};

export default App;

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { MapContainer, TileLayer, Marker, Popup } from 'react-leaflet';
import L from 'leaflet';
import { Vehicle, RoutesApiResponse, RawVehicle, ApiResponse } from './types';

// The original API endpoints are blocked by CORS policy.
const PROXY_URL = 'https://api.allorigins.win/raw?url=';
const VEHICLES_API_URL = `${PROXY_URL}${encodeURIComponent('https://ckan2.multimediagdansk.pl/gpsPositions?v=2')}`;
const ROUTES_API_URL = `${PROXY_URL}${encodeURIComponent('https://ckan.multimediagdansk.pl/dataset/c24aa637-3619-4dc2-a171-a23eec8f2172/resource/22313c56-5acf-41c7-a5fd-dc5dc72b3851/download/routes.json')}`;

const GDANSK_CENTER: L.LatLngExpression = [54.372158, 18.638306];
const REFRESH_INTERVAL = 5000;
const DELAY_THRESHOLD_SECONDS = 120;

// --- Helper Types ---
type IconShape = 'vehicle' | 'dot' | 'pin';
type VehicleTypeFilter = 'ALL' | 'BUS' | 'TRAM';
type DelayFilter = 'ALL' | 'ON_TIME' | 'DELAYED';

interface Settings {
  busColor: string;
  tramColor: string;
  busIconShape: IconShape;
  tramIconShape: IconShape;
  iconSizeScale: number; // 0.5 to 2.0
  isDarkMode: boolean;
}

interface Filters {
    line: string;
    type: VehicleTypeFilter;
    delay: DelayFilter;
}

const fetchWithRetry = async (url: string, retries = 2, delay = 500): Promise<Response> => {
  for (let i = 0; i <= retries; i++) {
    try {
      const response = await fetch(url);
      if (response.ok || response.status < 500) return response;
    } catch (error) {
      console.warn(`Attempt ${i + 1} for ${url} failed. Retrying...`);
    }
    if (i < retries) await new Promise(resolve => setTimeout(resolve, delay * Math.pow(2, i)));
  }
  throw new Error(`Failed to fetch from ${url}`);
};

// --- Vehicle Piktogramy ---
const BUS_PATH = "M18,11 L18,8 C18,6.89 17.1,6 16,6 L4,6 C2.89,6 2,6.89 2,8 L2,17 C2,18.1 2.89,19 4,19 L5,19 C5,20.1 5.9,21 7,21 C8.1,21 9,20.1 9,19 L15,19 C15,20.1 15.9,21 17,21 C18.1,21 19,20.1 19,19 L20,19 C21.1,19 22,18.1 22,17 L22,11 L18,11 Z";
const TRAM_PATH = "M13,5 L11,5 L11,2 L13,2 L13,5 Z M19,11 L19,8 C19,6.89 18.1,6 17,6 L7,6 C5.89,6 5,6.89 5,8 L5,17 C5,18.1 5.89,19 7,19 L17,19 C18.1,19 19,18.1 19,17 L19,11 Z";

// --- Helper Components ---
interface VehicleMarkerProps {
  vehicle: Vehicle;
  color: string;
  iconShape: IconShape;
  scale: number;
}

const VehicleMarker: React.FC<VehicleMarkerProps> = ({ vehicle, color, iconShape, scale }) => {
  const icon = useMemo(() => {
    const isTram = vehicle.vehicleType === 'TRAM';
    const isMoving = vehicle.speed > 0;
    const vehicleIconPath = isTram ? TRAM_PATH : BUS_PATH;
    let svg: string;
    let iconSize: [number, number];

    const shadowFilter = `filter: drop-shadow(0 1px 1.5px rgba(0,0,0,0.6));`;
    const arrowColor = "#ffffff";
    const directionalArrow = isMoving ? `<path d="M12,1 L16,6 L8,6 Z" fill="${arrowColor}" stroke="black" stroke-width="0.3" />` : '';

    switch (iconShape) {
      case 'dot':
        const line = vehicle.routeShortName;
        const fontSize = line.length > 2 ? '7px' : '9px';
        iconSize = [Math.round(28 * scale), Math.round(28 * scale)];
        svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="${iconSize[0]}" height="${iconSize[1]}" style="${shadowFilter}">
            <circle cx="12" cy="14" r="9" fill="${color}" stroke="white" stroke-width="1.2" />
            ${directionalArrow}
            <path d="${vehicleIconPath}" fill="white" transform="translate(8.5, 8.5) scale(0.3)" />
            <text x="12" y="21" dominant-baseline="auto" text-anchor="middle" fill="white" font-size="${fontSize}" font-weight="900" font-family="sans-serif">
              ${line}
            </text>
          </svg>`;
        break;

      case 'pin':
        iconSize = [Math.round(26 * scale), Math.round(32 * scale)];
        const pinArrow = isMoving ? `<path d="M12,0 L16,5 L8,5 Z" fill="${color}" stroke="white" stroke-width="0.5" />` : '';
        svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 30" fill="${color}" width="${iconSize[0]}" height="${iconSize[1]}" style="${shadowFilter}">
            ${pinArrow}
            <path d="M12 6C7.589 6 4 9.589 4 14c0 4.411 8 16 8 16s8-11.589 8-16c0-4.411-3.589-8-8-8zm0 12c-2.21 0-4-1.79-4-4s1.79-4 4-4 4 1.79 4 4-1.79 4-4 4z"/>
          </svg>`;
        break;

      case 'vehicle':
      default:
        if (isTram) {
          iconSize = [Math.round(40 * scale), Math.round(14 * scale)];
          svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 40 14" fill="${color}" width="${iconSize[0]}" height="${iconSize[1]}" style="${shadowFilter}">
              ${isMoving ? `<path d="M20,0 L24,4 L16,4 Z" fill="white" />` : ''}
              <rect x="0" y="4" width="19" height="10" rx="2" />
              <rect x="21" y="4" width="19" height="10" rx="2" />
              <rect x="18" y="7" width="4" height="4" fill="rgba(0,0,0,0.4)" rx="1"/>
            </svg>`;
        } else {
          iconSize = [Math.round(34 * scale), Math.round(18 * scale)];
          svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 34 18" fill="${color}" width="${iconSize[0]}" height="${iconSize[1]}" style="${shadowFilter}">
              ${isMoving ? `<path d="M17,0 L21,5 L13,5 Z" fill="white" />` : ''}
              <rect x="0" y="4" width="34" height="14" rx="3" />
              <rect x="4" y="7" width="26" height="8" fill="rgba(255,255,255,0.4)" rx="1" />
            </svg>`;
        }
        break;
    }

    const iconHtml = `
      <div style="transform-origin: center; transform: rotate(${vehicle.bearing}deg); transition: transform 0.5s linear; display: flex; align-items: center; justify-content: center;">
        ${svg}
      </div>
    `;

    return L.divIcon({
      html: iconHtml,
      className: '',
      iconSize: iconSize,
      iconAnchor: [iconSize[0] / 2, iconSize[1] / 2],
      popupAnchor: [0, -iconSize[1] / 2],
    });
  }, [vehicle.bearing, vehicle.vehicleType, color, iconShape, vehicle.routeShortName, vehicle.speed, scale]);

  const delayInMinutes = Math.round(vehicle.delay / 60);
  const delayText =
    delayInMinutes > 0
      ? `${delayInMinutes} min opóźnienia`
      : delayInMinutes < 0
      ? `${-delayInMinutes} min przyspieszenia`
      : 'punktualnie';
  const delayColor =
    delayInMinutes > 2 ? 'text-red-500' : delayInMinutes < -2 ? 'text-green-500' : 'text-gray-700 dark:text-gray-400';

  return (
    <Marker position={[vehicle.lat, vehicle.lon]} icon={icon}>
      <Popup>
        <div className="font-sans text-gray-800 dark:text-gray-300">
          <h3 className="font-bold text-lg mb-1 text-gray-900 dark:text-white">
            {vehicle.vehicleType === 'TRAM' ? 'Tramwaj' : 'Autobus'} Linii: {vehicle.routeShortName}
          </h3>
          <p><span className="font-semibold">Kierunek:</span> {vehicle.headsign}</p>
          <p><span className="font-semibold">Pojazd:</span> {vehicle.vehicleCode}</p>
          <p><span className="font-semibold">Prędkość:</span> {vehicle.speed} km/h</p>
          <p className={delayColor}><span className="font-semibold">Status:</span> {delayText}</p>
        </div>
      </Popup>
    </Marker>
  );
};

const App: React.FC = () => {
  const [vehicles, setVehicles] = useState<Vehicle[]>([]);
  const [routeInfo, setRouteInfo] = useState<Map<string, 'BUS' | 'TRAM'>>(new Map());
  const [lastUpdate, setLastUpdate] = useState<string>('');
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [initError, setInitError] = useState<string | null>(null);
  const [apiError, setApiError] = useState<string | null>(null);
  const isInitialLoad = useRef(true);

  const [filters, setFilters] = useState<Filters>({ line: '', type: 'ALL', delay: 'ALL' });
  const [isSettingsOpen, setIsSettingsOpen] = useState<boolean>(false);

  const loadSettings = (): Settings => {
    const defaultSettings: Settings = {
      busColor: '#2563EB',
      tramColor: '#DC2626',
      busIconShape: 'dot',
      tramIconShape: 'dot',
      iconSizeScale: 1.0,
      isDarkMode: window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches,
    };
    try {
      const saved = localStorage.getItem('gdanskTransportMapSettings_v2');
      if (!saved) return defaultSettings;
      const parsed = JSON.parse(saved);
      return parsed && typeof parsed === 'object' ? { ...defaultSettings, ...parsed } : defaultSettings;
    } catch { return defaultSettings; }
  };

  const [settings, setSettings] = useState<Settings>(loadSettings);

  useEffect(() => {
    localStorage.setItem('gdanskTransportMapSettings_v2', JSON.stringify(settings));
    const root = window.document.documentElement;
    settings.isDarkMode ? root.classList.add('dark') : root.classList.remove('dark');
  }, [settings]);

  useEffect(() => {
    const fetchRouteInfo = async () => {
      try {
        const response = await fetchWithRetry(ROUTES_API_URL);
        const data: RoutesApiResponse = await response.json();

        // Defensive check to prevent "Cannot convert undefined or null to object"
        if (!data || typeof data !== 'object') {
          throw new Error("Invalid routes data format");
        }

        const dataEntries = Object.values(data);
        if (dataEntries.length === 0) {
          throw new Error("Routes data is empty");
        }

        const routes = dataEntries[0]?.routes;
        if (!Array.isArray(routes)) {
          throw new Error("Routes format error: expected an array");
        }

        const newRouteInfo = new Map<string, 'BUS' | 'TRAM'>();
        for (const route of routes) {
          if (route?.routeShortName) {
            const isTram = /^\d{1,2}$/.test(route.routeShortName);
            newRouteInfo.set(route.routeShortName, isTram ? 'TRAM' : 'BUS');
          }
        }
        setRouteInfo(newRouteInfo);
      } catch (error) {
        console.error("Route fetch error:", error);
        setInitError("Nie można załadować informacji o liniach.");
        setIsLoading(false);
      }
    };
    fetchRouteInfo();
  }, []);

  const fetchVehicles = useCallback(async () => {
    if (routeInfo.size === 0) return;
    if (isInitialLoad.current) setIsLoading(true);

    try {
      const response = await fetchWithRetry(VEHICLES_API_URL);
      const data: ApiResponse = await response.json();

      if (!data || !Array.isArray(data.vehicles)) {
        throw new Error("Invalid vehicles data format");
      }

      const enriched: Vehicle[] = data.vehicles.map((v: RawVehicle) => ({
        ...v,
        vehicleType: routeInfo.get(v.routeShortName) || 'BUS',
      }));

      setVehicles(enriched);
      if (data.lastUpdate) setLastUpdate(data.lastUpdate);
      setApiError(null);
    } catch (error) {
      console.error("Vehicle fetch error:", error);
      setApiError("Problem z aktualizacją pozycji.");
    } finally {
      if (isInitialLoad.current) {
        setIsLoading(false);
        isInitialLoad.current = false;
      }
    }
  }, [routeInfo]);

  useEffect(() => {
    if (routeInfo.size > 0 && !initError) {
      fetchVehicles();
      const intervalId = setInterval(fetchVehicles, REFRESH_INTERVAL);
      return () => clearInterval(intervalId);
    }
  }, [fetchVehicles, routeInfo.size, initError]);

  const handleSettingsChange = <K extends keyof Settings>(key: K, value: Settings[K]) => {
    setSettings(prev => ({ ...prev, [key]: value }));
  };

  const handleFilterChange = <K extends keyof Filters>(key: K, value: Filters[K]) => {
    setFilters(prev => ({...prev, [key]: value}));
  };

  const filteredVehicles = useMemo(() => {
    const lines = filters.line.split(',').map(l => l.trim().toUpperCase()).filter(l => l !== '');
    return vehicles.filter(v => {
      const matchType = filters.type === 'ALL' || v.vehicleType === filters.type;
      const matchDelay = filters.delay === 'ALL' || (filters.delay === 'DELAYED' ? v.delay > DELAY_THRESHOLD_SECONDS : v.delay <= DELAY_THRESHOLD_SECONDS);
      const matchLine = lines.length === 0 || lines.includes(v.routeShortName.toUpperCase());
      return matchType && matchDelay && matchLine;
    });
  }, [vehicles, filters]);

  const tramCount = useMemo(() => filteredVehicles.filter(v => v.vehicleType === 'TRAM').length, [filteredVehicles]);
  const busCount = useMemo(() => filteredVehicles.filter(v => v.vehicleType === 'BUS').length, [filteredVehicles]);

  const FilterButton = ({ label, value, currentValue, onClick }: any) => (
    <button onClick={onClick} className={`px-3 py-1 text-xs rounded transition-colors ${currentValue === value ? 'bg-blue-600 text-white font-bold shadow-sm' : 'bg-gray-200 dark:bg-gray-600 text-gray-800 dark:text-gray-200 hover:bg-gray-300 dark:hover:bg-gray-500'}`}>
      {label}
    </button>
  );

  return (
    <div className="relative h-screen w-screen bg-white dark:bg-gray-900 overflow-hidden">
      <header className="absolute top-0 left-0 right-0 z-[1000] p-3 bg-white/90 dark:bg-black/80 backdrop-blur-md shadow-lg flex flex-col gap-2 transition-all">
        <div className="flex justify-between items-center gap-2">
            <div>
              <h1 className="text-lg md:text-xl font-bold dark:text-white flex items-center gap-2">
                <span className="text-blue-600 dark:text-blue-400">Gdańsk</span> Live
              </h1>
              <p className="text-[10px] text-gray-500 dark:text-gray-400 uppercase tracking-wider font-semibold">
                Odświeżanie co 5s • {lastUpdate || 'Ładowanie...'}
              </p>
            </div>
            <div className="flex items-center gap-2 md:gap-3 text-xs md:text-sm dark:text-white">
              <span className="flex items-center gap-1 bg-white/50 dark:bg-gray-800/50 px-2 py-1 rounded-full border border-gray-200 dark:border-gray-700">
                <div className="w-2.5 h-2.5 rounded-full" style={{ backgroundColor: settings.busColor }}></div> {busCount}
              </span>
              <span className="flex items-center gap-1 bg-white/50 dark:bg-gray-800/50 px-2 py-1 rounded-full border border-gray-200 dark:border-gray-700">
                <div className="w-2.5 h-2.5 rounded-full" style={{ backgroundColor: settings.tramColor }}></div> {tramCount}
              </span>
              <div className="h-6 w-[1px] bg-gray-300 dark:bg-gray-700 mx-1"></div>
              <button onClick={() => handleSettingsChange('isDarkMode', !settings.isDarkMode)} className="p-2 rounded-full bg-gray-100 dark:bg-gray-800 hover:bg-gray-200 dark:hover:bg-gray-700 transition-colors shadow-sm">
                {settings.isDarkMode ? '☀️' : '🌙'}
              </button>
              <button onClick={() => setIsSettingsOpen(!isSettingsOpen)} className="p-2 rounded-full bg-gray-100 dark:bg-gray-800 hover:bg-gray-200 dark:hover:bg-gray-700 transition-colors shadow-sm">
                ⚙️
              </button>
            </div>
        </div>

        <div className="flex flex-wrap gap-2 items-center">
          <input 
            type="text" 
            value={filters.line} 
            onChange={(e) => handleFilterChange('line', e.target.value)} 
            placeholder="Szukaj linii..." 
            className="bg-white dark:bg-gray-700 dark:text-white rounded-lg p-1.5 px-3 text-xs w-32 border border-gray-300 dark:border-gray-600 focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all" 
          />
          <FilterButton label="Wszystkie" value="ALL" currentValue={filters.type} onClick={() => handleFilterChange('type', 'ALL')} />
          <FilterButton label="Autobusy" value="BUS" currentValue={filters.type} onClick={() => handleFilterChange('type', 'BUS')} />
          <FilterButton label="Tramwaje" value="TRAM" currentValue={filters.type} onClick={() => handleFilterChange('type', 'TRAM')} />
          <FilterButton label="Opóźnione" value="DELAYED" currentValue={filters.delay} onClick={() => handleFilterChange('delay', 'DELAYED')} />
          {apiError && <span className="text-red-500 text-[10px] font-bold animate-pulse">⚠️ {apiError}</span>}
        </div>

        {isSettingsOpen && (
           <div className="bg-gray-50 dark:bg-gray-900/90 border border-gray-200 dark:border-gray-700 p-3 rounded-xl mt-1 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 animate-in slide-in-from-top-2 duration-200">
              <div className="flex flex-col gap-1.5">
                <label className="text-[10px] font-bold uppercase text-gray-500">Kolory</label>
                <div className="flex gap-4">
                  <div className="flex items-center gap-2">
                    <span className="text-[10px] dark:text-gray-400">Autobus:</span>
                    <input type="color" value={settings.busColor} onChange={(e) => handleSettingsChange('busColor', e.target.value)} className="w-6 h-6 rounded cursor-pointer border-none bg-transparent" />
                  </div>
                  <div className="flex items-center gap-2">
                    <span className="text-[10px] dark:text-gray-400">Tramwaj:</span>
                    <input type="color" value={settings.tramColor} onChange={(e) => handleSettingsChange('tramColor', e.target.value)} className="w-6 h-6 rounded cursor-pointer border-none bg-transparent" />
                  </div>
                </div>
              </div>

              <div className="flex flex-col gap-1.5">
                <label className="text-[10px] font-bold uppercase text-gray-500">Kształt Ikon</label>
                <div className="flex gap-2">
                  <select 
                    value={settings.busIconShape} 
                    onChange={(e) => handleSettingsChange('busIconShape', e.target.value as IconShape)} 
                    className="bg-white dark:bg-gray-800 border dark:border-gray-700 rounded p-1 text-[10px] dark:text-gray-300 flex-1"
                  >
                    <option value="dot">Kropka</option>
                    <option value="vehicle">Pojazd</option>
                    <option value="pin">Pinezka</option>
                  </select>
                </div>
              </div>

              <div className="flex flex-col gap-1.5 flex-1">
                <label className="text-[10px] font-bold uppercase text-gray-500">Rozmiar Ikon: {Math.round(settings.iconSizeScale * 100)}%</label>
                <input 
                  type="range" 
                  min="0.5" 
                  max="2.0" 
                  step="0.1" 
                  value={settings.iconSizeScale} 
                  onChange={(e) => handleSettingsChange('iconSizeScale', parseFloat(e.target.value))}
                  className="w-full h-1.5 bg-gray-200 dark:bg-gray-700 rounded-lg appearance-none cursor-pointer accent-blue-600"
                />
              </div>

              <div className="flex items-end justify-end">
                <button onClick={() => setIsSettingsOpen(false)} className="text-[10px] text-blue-600 dark:text-blue-400 font-bold hover:underline">Zamknij</button>
              </div>
           </div>
        )}
      </header>

      {(isLoading || initError) && (
        <div className="absolute inset-0 z-[1001] flex items-center justify-center bg-gray-100/50 dark:bg-gray-900/50 backdrop-blur-sm">
          <div className="p-6 bg-white dark:bg-gray-800 rounded-2xl shadow-2xl text-center border border-gray-200 dark:border-gray-700">
            {initError ? (
              <div className="text-red-500">
                <p className="text-3xl mb-2">⚠️</p>
                <p className="font-bold">{initError}</p>
                <button onClick={() => window.location.reload()} className="mt-4 px-4 py-2 bg-red-500 text-white rounded-lg text-sm">Spróbuj ponownie</button>
              </div>
            ) : (
              <div className="flex flex-col items-center gap-4">
                <div className="w-12 h-12 border-4 border-blue-600 border-t-transparent rounded-full animate-spin"></div>
                <p className="font-medium text-gray-700 dark:text-gray-300">Pobieranie danych GPS...</p>
              </div>
            )}
          </div>
        </div>
      )}

      <MapContainer center={GDANSK_CENTER} zoom={13} scrollWheelZoom={true} zoomControl={false}>
        <TileLayer
          attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'
          url={settings.isDarkMode ? "https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png" : "https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"}
        />
        <L.Control.Zoom position="bottomright" />
        {filteredVehicles.map(v => (
          <VehicleMarker 
            key={v.vehicleId} 
            vehicle={v}
            color={v.vehicleType === 'TRAM' ? settings.tramColor : settings.busColor}
            iconShape={v.vehicleType === 'TRAM' ? settings.tramIconShape : settings.busIconShape}
            scale={settings.iconSizeScale}
          />
        ))}
      </MapContainer>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { MapContainer, TileLayer, Marker, Popup } from 'react-leaflet';
import L from 'leaflet';
import { Vehicle, RoutesApiResponse, RawVehicle, ApiResponse } from './types';

// The original API endpoints are blocked by CORS policy.
const PROXY_URL = 'https://api.allorigins.win/raw?url=';
const VEHICLES_API_URL = `${PROXY_URL}${encodeURIComponent('https://ckan2.multimediagdansk.pl/gpsPositions?v=2')}`;
const ROUTES_API_URL = `${PROXY_URL}${encodeURIComponent('https://ckan.multimediagdansk.pl/dataset/c24aa637-3619-4dc2-a171-a23eec8f2172/resource/22313c56-5acf-41c7-a5fd-dc5dc72b3851/download/routes.json')}`;

const GDANSK_CENTER: L.LatLngExpression = [54.372158, 18.638306];
const REFRESH_INTERVAL = 5000;
const DELAY_THRESHOLD_SECONDS = 120;

// --- Helper Types ---
type IconShape = 'vehicle' | 'dot' | 'pin';
type VehicleTypeFilter = 'ALL' | 'BUS' | 'TRAM';
type DelayFilter = 'ALL' | 'ON_TIME' | 'DELAYED';

interface Settings {
  busColor: string;
  tramColor: string;
  busIconShape: IconShape;
  tramIconShape: IconShape;
  iconSizeScale: number;
  isDarkMode: boolean;
}

interface Filters {
    line: string;
    type: VehicleTypeFilter;
    delay: DelayFilter;
}

const fetchWithRetry = async (url: string, retries = 2, delay = 500): Promise<Response> => {
  for (let i = 0; i <= retries; i++) {
    try {
      const response = await fetch(url);
      if (response.ok || response.status < 500) return response;
    } catch (error) {
      console.warn(`Attempt ${i + 1} for ${url} failed. Retrying...`);
    }
    if (i < retries) await new Promise(resolve => setTimeout(resolve, delay * Math.pow(2, i)));
  }
  throw new Error(`Failed to fetch from ${url}`);
};

// --- Vehicle Piktogramy ---
const BUS_PATH = "M18,11 L18,8 C18,6.89 17.1,6 16,6 L4,6 C2.89,6 2,6.89 2,8 L2,17 C2,18.1 2.89,19 4,19 L5,19 C5,20.1 5.9,21 7,21 C8.1,21 9,20.1 9,19 L15,19 C15,20.1 15.9,21 17,21 C18.1,21 19,20.1 19,19 L20,19 C21.1,19 22,18.1 22,17 L22,11 L18,11 Z";
const TRAM_PATH = "M13,5 L11,5 L11,2 L13,2 L13,5 Z M19,11 L19,8 C19,6.89 18.1,6 17,6 L7,6 C5.89,6 5,6.89 5,8 L5,17 C5,18.1 5.89,19 7,19 L17,19 C18.1,19 19,18.1 19,17 L19,11 Z";

interface VehicleMarkerProps {
  vehicle: Vehicle;
  color: string;
  iconShape: IconShape;
  scale: number;
}

const VehicleMarker: React.FC<VehicleMarkerProps> = ({ vehicle, color, iconShape, scale = 1.0 }) => {
  const icon = useMemo(() => {
    if (!vehicle) return null;
    const isTram = vehicle.vehicleType === 'TRAM';
    const isMoving = vehicle.speed > 0;
    const vehicleIconPath = isTram ? TRAM_PATH : BUS_PATH;
    let svg: string;
    let iconSize: [number, number];

    const shadowFilter = `filter: drop-shadow(0 1px 1.5px rgba(0,0,0,0.6));`;
    const arrowColor = "#ffffff";
    const directionalArrow = isMoving ? `<path d="M12,1 L16,6 L8,6 Z" fill="${arrowColor}" stroke="black" stroke-width="0.3" />` : '';

    switch (iconShape) {
      case 'dot':
        const line = vehicle.routeShortName || '?';
        const fontSize = line.length > 2 ? '7px' : '9px';
        iconSize = [Math.round(28 * scale), Math.round(28 * scale)];
        svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" width="${iconSize[0]}" height="${iconSize[1]}" style="${shadowFilter}">
            <circle cx="12" cy="14" r="9" fill="${color}" stroke="white" stroke-width="1.2" />
            ${directionalArrow}
            <path d="${vehicleIconPath}" fill="white" transform="translate(8.5, 8.5) scale(0.3)" />
            <text x="12" y="21" dominant-baseline="auto" text-anchor="middle" fill="white" font-size="${fontSize}" font-weight="900" font-family="sans-serif">
              ${line}
            </text>
          </svg>`;
        break;

      case 'pin':
        iconSize = [Math.round(26 * scale), Math.round(32 * scale)];
        const pinArrow = isMoving ? `<path d="M12,0 L16,5 L8,5 Z" fill="${color}" stroke="white" stroke-width="0.5" />` : '';
        svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 30" fill="${color}" width="${iconSize[0]}" height="${iconSize[1]}" style="${shadowFilter}">
            ${pinArrow}
            <path d="M12 6C7.589 6 4 9.589 4 14c0 4.411 8 16 8 16s8-11.589 8-16c0-4.411-3.589-8-8-8zm0 12c-2.21 0-4-1.79-4-4s1.79-4 4-4 4 1.79 4 4-1.79 4-4 4z"/>
          </svg>`;
        break;

      case 'vehicle':
      default:
        if (isTram) {
          iconSize = [Math.round(40 * scale), Math.round(14 * scale)];
          svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 40 14" fill="${color}" width="${iconSize[0]}" height="${iconSize[1]}" style="${shadowFilter}">
              ${isMoving ? `<path d="M20,0 L24,4 L16,4 Z" fill="white" />` : ''}
              <rect x="0" y="4" width="19" height="10" rx="2" />
              <rect x="21" y="4" width="19" height="10" rx="2" />
              <rect x="18" y="7" width="4" height="4" fill="rgba(0,0,0,0.4)" rx="1"/>
            </svg>`;
        } else {
          iconSize = [Math.round(34 * scale), Math.round(18 * scale)];
          svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 34 18" fill="${color}" width="${iconSize[0]}" height="${iconSize[1]}" style="${shadowFilter}">
              ${isMoving ? `<path d="M17,0 L21,5 L13,5 Z" fill="white" />` : ''}
              <rect x="0" y="4" width="34" height="14" rx="3" />
              <rect x="4" y="7" width="26" height="8" fill="rgba(255,255,255,0.4)" rx="1" />
            </svg>`;
        }
        break;
    }

    const iconHtml = `
      <div style="transform-origin: center; transform: rotate(${vehicle.bearing || 0}deg); transition: transform 0.5s linear; display: flex; align-items: center; justify-content: center;">
        ${svg}
      </div>
    `;

    return L.divIcon({
      html: iconHtml,
      className: '',
      iconSize: iconSize,
      iconAnchor: [iconSize[0] / 2, iconSize[1] / 2],
      popupAnchor: [0, -iconSize[1] / 2],
    });
  }, [vehicle, color, iconShape, scale]);

  if (!icon) return null;

  const delayInMinutes = Math.round((vehicle.delay || 0) / 60);
  const delayText =
    delayInMinutes > 0
      ? `${delayInMinutes} min opóźnienia`
      : delayInMinutes < 0
      ? `${-delayInMinutes} min przyspieszenia`
      : 'punktualnie';
  const delayColor =
    delayInMinutes > 2 ? 'text-red-500' : delayInMinutes < -2 ? 'text-green-500' : 'text-gray-700 dark:text-gray-400';

  return (
    <Marker position={[vehicle.lat, vehicle.lon]} icon={icon}>
      <Popup>
        <div className="font-sans text-gray-800 dark:text-gray-300">
          <h3 className="font-bold text-lg mb-1 text-gray-900 dark:text-white">
            {vehicle.vehicleType === 'TRAM' ? 'Tramwaj' : 'Autobus'} Linii: {vehicle.routeShortName}
          </h3>
          <p><span className="font-semibold">Kierunek:</span> {vehicle.headsign || 'Nieznany'}</p>
          <p><span className="font-semibold">Pojazd:</span> {vehicle.vehicleCode}</p>
          <p><span className="font-semibold">Prędkość:</span> {vehicle.speed} km/h</p>
          <p className={delayColor}><span className="font-semibold">Status:</span> {delayText}</p>
        </div>
      </Popup>
    </Marker>
  );
};

const App: React.FC = () => {
  const [vehicles, setVehicles] = useState<Vehicle[]>([]);
  const [routeInfo, setRouteInfo] = useState<Map<string, 'BUS' | 'TRAM'>>(new Map());
  const [lastUpdate, setLastUpdate] = useState<string>('');
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [initError, setInitError] = useState<string | null>(null);
  const [apiError, setApiError] = useState<string | null>(null);
  const isInitialLoad = useRef(true);

  const [filters, setFilters] = useState<Filters>({ line: '', type: 'ALL', delay: 'ALL' });
  const [isSettingsOpen, setIsSettingsOpen] = useState<boolean>(false);

  const loadSettings = useCallback((): Settings => {
    const defaultSettings: Settings = {
      busColor: '#2563EB',
      tramColor: '#DC2626',
      busIconShape: 'dot',
      tramIconShape: 'dot',
      iconSizeScale: 1.0,
      isDarkMode: window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches,
    };
    try {
      const saved = localStorage.getItem('gdanskTransportMapSettings_v3');
      if (!saved) return defaultSettings;
      const parsed = JSON.parse(saved);
      if (parsed && typeof parsed === 'object') {
        return { ...defaultSettings, ...parsed };
      }
    } catch { 
      return defaultSettings; 
    }
    return defaultSettings;
  }, []);

  const [settings, setSettings] = useState<Settings>(loadSettings);

  useEffect(() => {
    localStorage.setItem('gdanskTransportMapSettings_v3', JSON.stringify(settings));
    const root = window.document.documentElement;
    settings.isDarkMode ? root.classList.add('dark') : root.classList.remove('dark');
  }, [settings]);

  useEffect(() => {
    const fetchRouteInfo = async () => {
      try {
        const response = await fetchWithRetry(ROUTES_API_URL);
        const data = await response.json();

        if (!data || typeof data !== 'object' || data === null) {
          throw new Error("Invalid data format received from API");
        }

        const dataEntries = Object.values(data);
        if (dataEntries.length === 0) {
          throw new Error("Route dictionary is empty");
        }

        const firstEntry = dataEntries[0] as any;
        const routes = firstEntry?.routes;
        if (!Array.isArray(routes)) {
          throw new Error("Missing routes array in response");
        }

        const newRouteInfo = new Map<string, 'BUS' | 'TRAM'>();
        for (const route of routes) {
          if (route?.routeShortName) {
            const isTram = /^\d{1,2}$/.test(route.routeShortName);
            newRouteInfo.set(route.routeShortName, isTram ? 'TRAM' : 'BUS');
          }
        }
        setRouteInfo(newRouteInfo);
      } catch (error) {
        console.error("Route metadata error:", error);
        setInitError("Błąd inicjalizacji metadanych linii.");
        setIsLoading(false);
      }
    };
    fetchRouteInfo();
  }, []);

  const fetchVehicles = useCallback(async () => {
    if (routeInfo.size === 0) return;
    if (isInitialLoad.current) setIsLoading(true);

    try {
      const response = await fetchWithRetry(VEHICLES_API_URL);
      const data: ApiResponse = await response.json();

      if (!data || !Array.isArray(data.vehicles)) {
        throw new Error("Invalid vehicles format");
      }

      const enriched: Vehicle[] = data.vehicles.map((v: RawVehicle) => ({
        ...v,
        vehicleType: routeInfo.get(v.routeShortName) || 'BUS',
      }));

      setVehicles(enriched);
      if (data.lastUpdate) setLastUpdate(data.lastUpdate);
      setApiError(null);
    } catch (error) {
      console.error("Position update error:", error);
      setApiError("Problem z pobieraniem pozycji GPS.");
    } finally {
      if (isInitialLoad.current) {
        setIsLoading(false);
        isInitialLoad.current = false;
      }
    }
  }, [routeInfo]);

  useEffect(() => {
    if (routeInfo.size > 0 && !initError) {
      fetchVehicles();
      const intervalId = setInterval(fetchVehicles, REFRESH_INTERVAL);
      return () => clearInterval(intervalId);
    }
  }, [fetchVehicles, routeInfo.size, initError]);

  const handleSettingsChange = <K extends keyof Settings>(key: K, value: Settings[K]) => {
    setSettings(prev => ({ ...prev, [key]: value }));
  };

  const handleFilterChange = <K extends keyof Filters>(key: K, value: Filters[K]) => {
    setFilters(prev => ({...prev, [key]: value}));
  };

  const filteredVehicles = useMemo(() => {
    const lines = filters.line.split(',').map(l => l.trim().toUpperCase()).filter(l => l !== '');
    return vehicles.filter(v => {
      const matchType = filters.type === 'ALL' || v.vehicleType === filters.type;
      const matchDelay = filters.delay === 'ALL' || (filters.delay === 'DELAYED' ? v.delay > DELAY_THRESHOLD_SECONDS : v.delay <= DELAY_THRESHOLD_SECONDS);
      const matchLine = lines.length === 0 || lines.includes((v.routeShortName || "").toUpperCase());
      return matchType && matchDelay && matchLine;
    });
  }, [vehicles, filters]);

  const tramCount = useMemo(() => filteredVehicles.filter(v => v.vehicleType === 'TRAM').length, [filteredVehicles]);
  const busCount = useMemo(() => filteredVehicles.filter(v => v.vehicleType === 'BUS').length, [filteredVehicles]);

  const FilterButton = ({ label, value, currentValue, onClick }: any) => (
    <button onClick={onClick} className={`px-3 py-1 text-xs rounded transition-colors ${currentValue === value ? 'bg-blue-600 text-white font-bold shadow-sm' : 'bg-gray-200 dark:bg-gray-600 text-gray-800 dark:text-gray-200 hover:bg-gray-300 dark:hover:bg-gray-500'}`}>
      {label}
    </button>
  );

  return (
    <div className="relative h-screen w-screen bg-white dark:bg-gray-900 overflow-hidden">
      <header className="absolute top-0 left-0 right-0 z-[1000] p-3 bg-white/90 dark:bg-black/80 backdrop-blur-md shadow-lg flex flex-col gap-2 transition-all">
        <div className="flex justify-between items-center gap-2">
            <div>
