const App: React.FC = () => {
  const [vehicles, setVehicles] = useState<Vehicle[]>([]);
  const [routeInfo, setRouteInfo] = useState<Map<string, 'BUS' | 'TRAM'>>(new Map());
  const [lastUpdate, setLastUpdate] = useState<string>('');
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [initError, setInitError] = useState<string | null>(null);
  const [apiError, setApiError] = useState<string | null>(null);
  const isInitialLoad = useRef(true);

  const [filters, setFilters] = useState<Filters>({ line: '', type: 'ALL', delay: 'ALL' });
  const [isSettingsOpen, setIsSettingsOpen] = useState<boolean>(false);

  const loadSettings = (): Settings => {
    const defaultSettings: Settings = {
      busColor: '#2563EB',
      tramColor: '#DC2626',
      busIconShape: 'dot',
      tramIconShape: 'dot',
      isDarkMode: window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches,
    };
    try {
      const saved = localStorage.getItem('gdanskTransportMapSettings');
      if (!saved) return defaultSettings;
      const parsed = JSON.parse(saved);
      // Sprawdź czy parsed jest obiektem i nie jest null przed spreadem
      return (parsed && typeof parsed === 'object') ? { ...defaultSettings, ...parsed } : defaultSettings;
    } catch { return defaultSettings; }
  };

  const [settings, setSettings] = useState<Settings>(loadSettings);

  useEffect(() => {
    localStorage.setItem('gdanskTransportMapSettings', JSON.stringify(settings));
    const root = window.document.documentElement;
    settings.isDarkMode ? root.classList.add('dark') : root.classList.remove('dark');
  }, [settings]);

  useEffect(() => {
    const fetchRouteInfo = async () => {
      try {
        const response = await fetchWithRetry(ROUTES_API_URL);
        const data: RoutesApiResponse = await response.json();

        // ZABEZPIECZENIE: Rygorystyczne sprawdzenie danych wejściowych
        if (!data || typeof data !== 'object' || data === null) {
            throw new Error("Invalid format - data is not an object");
        }

        const dataValues = Object.values(data);
        if (dataValues.length === 0) throw new Error("Format error - empty object");

        const firstEntry = dataValues[0] as any;
        const routes = firstEntry?.routes;
        if (!routes || !Array.isArray(routes)) throw new Error("Format error - missing routes array");

        const newRouteInfo = new Map<string, 'BUS' | 'TRAM'>();
        for (const route of routes) {
          if (route?.routeShortName) {
            const isTram = /^\d{1,2}$/.test(route.routeShortName);
            newRouteInfo.set(route.routeShortName, isTram ? 'TRAM' : 'BUS');
          }
        }
        setRouteInfo(newRouteInfo);
      } catch (error) {
        console.error(error);
        setInitError("Nie można załadować informacji o liniach.");
        setIsLoading(false);
      }
    };
    fetchRouteInfo();
  }, []);

  const fetchVehicles = useCallback(async () => {
    if (routeInfo.size === 0) return;
    if (isInitialLoad.current) setIsLoading(true);

    try {
      const response = await fetchWithRetry(VEHICLES_API_URL);
      const data: ApiResponse = await response.json();

      // ZABEZPIECZENIE: Sprawdzenie czy data i data.vehicles istnieją i są tablicą
      if (!data || !data.vehicles || !Array.isArray(data.vehicles)) {
          throw new Error("Missing or invalid vehicle data");
      }

      const enriched: Vehicle[] = data.vehicles.map((v: RawVehicle) => ({
        ...v,
        vehicleType: routeInfo.get(v.routeShortName) || 'BUS',
      }));

      setVehicles(enriched);
      if (data.lastUpdate) setLastUpdate(data.lastUpdate);
      setApiError(null);
    } catch (error) {
      console.error(error);
      setApiError("Problem z aktualizacją pozycji.");
    } finally {
      if (isInitialLoad.current) {
        setIsLoading(false);
        isInitialLoad.current = false;
      }
    }
  }, [routeInfo]);

  useEffect(() => {
    if (routeInfo.size > 0 && !initError) {
      fetchVehicles();
      const intervalId = setInterval(fetchVehicles, REFRESH_INTERVAL);
      return () => clearInterval(intervalId);
    }
  }, [fetchVehicles, routeInfo.size, initError]);

  const handleSettingsChange = <K extends keyof Settings>(key: K, value: Settings[K]) => {
    setSettings(prev => ({ ...prev, [key]: value }));
  };

  const handleFilterChange = <K extends keyof Filters>(key: K, value: Filters[K]) => {
    setFilters(prev => ({...prev, [key]: value}));
  };

  const filteredVehicles = useMemo(() => {
    const lines = filters.line.split(',').map(l => l.trim().toUpperCase()).filter(l => l !== '');
    return vehicles.filter(v => {
      const matchType = filters.type === 'ALL' || v.vehicleType === filters.type;
      const matchDelay = filters.delay === 'ALL' || (filters.delay === 'DELAYED' ? v.delay > DELAY_THRESHOLD_SECONDS : v.delay <= DELAY_THRESHOLD_SECONDS);
      // ZABEZPIECZENIE: Safe access to routeShortName
      const routeName = (v.routeShortName || "").toUpperCase();
      const matchLine = lines.length === 0 || lines.includes(routeName);
      return matchType && matchDelay && matchLine;
    });
  }, [vehicles, filters]);

  const tramCount = useMemo(() => filteredVehicles.filter(v => v.vehicleType === 'TRAM').length, [filteredVehicles]);
  const busCount = useMemo(() => filteredVehicles.filter(v => v.vehicleType === 'BUS').length, [filteredVehicles]);

  const FilterButton = ({ label, value, currentValue, onClick }: any) => (
    <button onClick={onClick} className={`px-3 py-1 text-xs rounded transition-colors ${currentValue === value ? 'bg-blue-600 text-white font-bold' : 'bg-gray-200 dark:bg-gray-600 text-gray-800 dark:text-gray-200'}`}>
      {label}
    </button>
  );

  return (
    <div className="relative h-screen w-screen bg-white dark:bg-gray-900">
      {/* NAGŁÓWEK - PRZYWRÓCONY DO PIERWOTNEJ STRUKTURY */}
      <header className="absolute top-0 left-0 right-0 z-[1000] p-3 bg-white/80 dark:bg-black/70 backdrop-blur-sm shadow-md flex flex-col gap-2">
        <div className="flex justify-between items-center gap-2">
            <div>
              <h1 className="text-lg md:text-xl font-bold dark:text-white">Gdańsk Live</h1>
              <p className="text-[10px] text-gray-500 dark:text-gray-400">Aktualizacja co 5s • {lastUpdate || 'Ładowanie...'}</p>
            </div>
            <div className="flex items-center gap-3 text-xs md:text-sm dark:text-white">
              <span className="flex items-center gap-1"><div className="w-3 h-3 rounded-full" style={{ backgroundColor: settings.busColor }}></div> {busCount}</span>
              <span className="flex items-center gap-1"><div className="w-3 h-3 rounded-full" style={{ backgroundColor: settings.tramColor }}></div> {tramCount}</span>
              <button onClick={() => handleSettingsChange('isDarkMode', !settings.isDarkMode)} className="p-1.5 rounded bg-gray-200 dark:bg-gray-700">
                {settings.isDarkMode ? '☀️' : '🌙'}
              </button>
              <button onClick={() => setIsSettingsOpen(!isSettingsOpen)} className="p-1.5 rounded bg-gray-200 dark:bg-gray-700">⚙️</button>
            </div>
        </div>

        <div className="flex flex-wrap gap-2 items-center text-xs">
          <input type="text" value={filters.line} onChange={(e) => handleFilterChange('line', e.target.value)} placeholder="Linie (np. 2, 6)" className="bg-white dark:bg-gray-700 dark:text-white rounded p-1 w-24 border border-gray-300 dark:border-gray-600" />
          <FilterButton label="Wsz." value="ALL" currentValue={filters.type} onClick={() => handleFilterChange('type', 'ALL')} />
          <FilterButton label="Aut." value="BUS" currentValue={filters.type} onClick={() => handleFilterChange('type', 'BUS')} />
          <FilterButton label="Tra." value="TRAM" currentValue={filters.type} onClick={() => handleFilterChange('type', 'TRAM')} />
          <FilterButton label="Opóźn." value="DELAYED" currentValue={filters.delay} onClick={() => handleFilterChange('delay', 'DELAYED')} />
          {apiError && <span className="text-red-500 text-[10px] ml-2 animate-pulse">{apiError}</span>}
        </div>

        {isSettingsOpen && (
           <div className="bg-gray-100 dark:bg-gray-800 p-2 rounded flex flex-wrap gap-3 text-[10px] dark:text-gray-300 shadow-inner">
              <div className="flex items-center gap-1">Autobus: <input type="color" value={settings.busColor} onChange={(e) => handleSettingsChange('busColor', e.target.value)} className="w-5 h-5 border-none bg-transparent" /></div>
              <div className="flex items-center gap-1">Tramwaj: <input type="color" value={settings.tramColor} onChange={(e) => handleSettingsChange('tramColor', e.target.value)} className="w-5 h-5 border-none bg-transparent" /></div>
              <div className="flex items-center gap-1">Ikony: 
                <select value={settings.busIconShape} onChange={(e) => handleSettingsChange('busIconShape', e.target.value as IconShape)} className="bg-transparent border rounded p-0.5 dark:bg-gray-700">
                  <option value="dot">Kropka</option>
                  <option value="vehicle">Pojazd</option>
                  <option value="pin">Pinezka</option>
                </select>
              </div>
           </div>
        )}
      </header>

      {(isLoading || initError) && (
        <div className="absolute inset-0 z-[1001] flex items-center justify-center bg-gray-100/50 dark:bg-gray-900/50 backdrop-blur-sm">
          <div className="p-4 bg-white dark:bg-gray-800 rounded-lg shadow-xl text-center border border-gray-200 dark:border-gray-700">
            {initError ? <p className="text-red-500 font-bold">{initError}</p> : <p className="animate-pulse dark:text-white">Inicjalizacja danych...</p>}
          </div>
        </div>
      )}

      <MapContainer center={GDANSK_CENTER} zoom={13} scrollWheelZoom={true} zoomControl={false}>
        <TileLayer
          attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'
          url={settings.isDarkMode ? "https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png" : "https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"}
        />
        <L.Control.Zoom position="bottomright" />
        {filteredVehicles.map(v => (
          <VehicleMarker 
            key={v.vehicleId} 
            vehicle={v}
            color={v.vehicleType === 'TRAM' ? settings.tramColor : settings.busColor}
            iconShape={v.vehicleType === 'TRAM' ? settings.tramIconShape : settings.busIconShape}
          />
        ))}
      </MapContainer>
    </div>
  );
};

export default App;

